-- ============================================================
-- 打印机配置权限调整（2026-08-29）
-- 1) 清理旧 WMS 打印机设备接口（/api/v1/tenant-printers/*）的失效权限配置
-- 2) 新增租客员工可见的打印机型号 / 标签规格查询权限
-- 说明：先删子表再删父表，符合外键依赖顺序；该段可随全量初始化或单独执行
-- ============================================================
DELETE FROM sys_permission WHERE perm_code IN (
    'perm_api_wms_create_printer',
    'perm_api_wms_delete_printer',
    'perm_api_wms_detail_printer',
    'perm_api_wms_query_printer',
    'perm_api_wms_search_printer',
    'perm_api_wms_update_printer'
);
DELETE FROM sys_api_function WHERE api_id IN (
    'api_wms_create_printer',
    'api_wms_delete_printer',
    'api_wms_detail_printer',
    'api_wms_query_printer',
    'api_wms_search_printer',
    'api_wms_update_printer'
);
DELETE FROM sys_button WHERE button_id IN (
    'btn_wms_create_printer',
    'btn_wms_delete_printer',
    'btn_wms_detail_printer',
    'btn_wms_query_printer',
    'btn_wms_search_printer',
    'btn_wms_update_printer'
);
