-- 权限并入既有外部品号全部权限（待执行库执行 UPDATE；下方 INSERT IGNORE 为幂等全量等价形式）
UPDATE `sys_permission` SET `function_id` = JSON_ARRAY_APPEND(`function_id`, '$', 'api_prod_ext_item_no_search')
WHERE `perm_code` = 'perm_api_prod_ext_item_no_all';

